import { describe, expect, it } from 'vitest';
import { LOG_VERSION, SAMPLE_LOG, parseFlightCSV, flightCSVHash } from './flightLog';
import { windowNotebook } from './windowNotebook';
import { NOTEBOOK_BUNDLE_VERSION, MAX_NOTEBOOK_BUNDLE_BYTES, createNotebookSourceBundle, readNotebookSourceBundle } from './notebookSourceBundle';
const entries=[{id:'a',first_row:3,last_row:5,label:'讨论 🚁',notes:'Private notes\nwith new line'},{id:'b',first_row:4,last_row:4,label:'Gap endpoint',notes:''}];
const source=async(csv_text=SAMPLE_LOG)=>({model_version:LOG_VERSION,filename:'recorded.csv',csv_text,sha256:await flightCSVHash(csv_text),samples:parseFlightCSV(csv_text),title:'EXCLUDE-TITLE',notes:'EXCLUDE-ANALYST',id:'EXCLUDE-BACKEND'});
describe('exact source plus saved notebook bundle',()=>{
 it('roundtrips full exact bytes and saved order/annotations without extra review/backend state or computed summaries',async()=>{const log=await source(),text=await createNotebookSourceBundle(log,entries),opened=await readNotebookSourceBundle(text);expect(opened.log.csv_text).toBe(SAMPLE_LOG);expect(opened.log.samples).toEqual(log.samples);expect(opened.log.title).toBe('recorded');expect(opened.log.notes).toBe('');expect(opened.data.notebook.windows).toEqual(entries);expect(opened.data.format).toBe(NOTEBOOK_BUNDLE_VERSION);expect(Object.keys(opened.data).sort()).toEqual(['format','replay_model','source','notebook'].sort());for(const textValue of ['EXCLUDE-','summary','markers','comparison','cursor'])expect(text).not.toContain(textValue);});
 it('retains BOM/CRLF/trailing whitespace exactsource bytes, never normalizes before hashing/export',async()=>{const csv='\uFEFF'+SAMPLE_LOG.replaceAll('\n','\r\n')+'\r\n ',log=await source(csv),opened=await readNotebookSourceBundle(await createNotebookSourceBundle(log,entries));expect(opened.log.csv_text).toBe(csv);expect(opened.log.sha256).toBe(await flightCSVHash(csv));expect(opened.log.sha256).not.toBe(await flightCSVHash(SAMPLE_LOG));});
 it('retains entire source including outside selected rows/coordinates and missing cells/gaps',async()=>{const log=await source(),text=await createNotebookSourceBundle(log,[entries[1]]),opened=await readNotebookSourceBundle(text);expect(opened.log.samples).toHaveLength(6);expect(opened.log.samples[0].latitude).toBe(28.6139);expect(opened.log.samples[3].altitude_m).toBeNull();expect(opened.data.notebook.windows[0]).toMatchObject({first_row:4,last_row:4});});
 it('supports20overlapping copies and preserves exact notebook-only schema unchanged',async()=>{const log=await source(),windows=Array.from({length:20},(_,i)=>({...entries[0],id:'w'+i})),opened=await readNotebookSourceBundle(await createNotebookSourceBundle(log,windows));expect(opened.data.notebook).toEqual(windowNotebook(log,windows));expect(Object.keys(opened.data.notebook.windows[0]).sort()).toEqual(['id','first_row','last_row','label','notes'].sort());});
 it('rejects source-byte mismatch on export/import and notebook hash that mismatches exact embedded source',async()=>{const log=await source();await expect(createNotebookSourceBundle({...log,csv_text:SAMPLE_LOG+'\n'},entries)).rejects.toThrow('fingerprint mismatch');const data=JSON.parse(await createNotebookSourceBundle(log,entries));data.source.csv_text+='\n';await expect(readNotebookSourceBundle(JSON.stringify(data))).rejects.toThrow('fingerprint mismatch');data.source.csv_text=log.csv_text;data.notebook.source_sha256='b'.repeat(64);await expect(readNotebookSourceBundle(JSON.stringify(data))).rejects.toThrow('fingerprint mismatch');});
 it.each([{format:'future'},{replay_model:'future'},{computed:{}},{notebook:null},{source:null}])('rejects unsupported structure %j',async patch=>{const data=JSON.parse(await createNotebookSourceBundle(await source(),entries));await expect(readNotebookSourceBundle(JSON.stringify({...data,...patch}))).rejects.toThrow();});
 it('strictly rejects unknown source/notebook/window fields, malformed models/rowbounds/IDs/annotations',async()=>{const data=JSON.parse(await createNotebookSourceBundle(await source(),entries));const cases=[{...data,source:{...data.source,id:'x'}},{...data,source:{...data.source,filename:''}},{...data,source:{...data.source,filename:'a'.repeat(121)}},{...data,notebook:{...data.notebook,format:'future'}},{...data,notebook:{...data.notebook,window_model:'future'}},{...data,notebook:{...data.notebook,summary:{}}},...[{first_row:0},{last_row:7},{first_row:5,last_row:3},{first_row:1.5},{notes:1},{label:''},{summary:{}}].map(patch=>({...data,notebook:{...data.notebook,windows:[{...entries[0],...patch}]}}))];for(const value of cases)await expect(readNotebookSourceBundle(JSON.stringify(value))).rejects.toThrow();});
 it('rejects empty saved notebook/missing csv/unsupported source even if raw samples look plausible',async()=>{const log=await source();await expect(createNotebookSourceBundle(log,[])).rejects.toThrow('at least one');await expect(createNotebookSourceBundle({...log,csv_text:undefined},entries)).rejects.toThrow();await expect(createNotebookSourceBundle({...log,model_version:'future'},entries)).rejects.toThrow();await expect(createNotebookSourceBundle(null,entries)).rejects.toThrow();});
 it('parses source rather than trusting caller samples or injected computed values',async()=>{const log=await source(),opened=await readNotebookSourceBundle(await createNotebookSourceBundle({...log,samples:[{time_s:999}]},entries));expect(opened.log.samples).toEqual(log.samples);expect(opened.log.samples[0].time_s).toBe(0);const data=JSON.parse(await createNotebookSourceBundle(log,entries));data.source.csv_text='not a valid CSV';data.source.sha256=await flightCSVHash(data.source.csv_text);await expect(readNotebookSourceBundle(JSON.stringify(data))).rejects.toThrow('Expected exact header');});
 it('rejects invalid JSON/nontext/arrays and oversized UTF8 before partial open',async()=>{for(const text of [null,{},'bad','null','[]','{}'])await expect(readNotebookSourceBundle(text)).rejects.toThrow();await expect(readNotebookSourceBundle(' '.repeat(MAX_NOTEBOOK_BUNDLE_BYTES+1))).rejects.toThrow('2MiB');await expect(readNotebookSourceBundle('😀'.repeat(MAX_NOTEBOOK_BUNDLE_BYTES/4+1))).rejects.toThrow('2MiB');const data=JSON.parse(await createNotebookSourceBundle(await source(),entries));data.source.csv_text=' '.repeat(1024*1024+1);await expect(readNotebookSourceBundle(JSON.stringify(data))).rejects.toThrow('CSV size');});
 it('applies2MiB limit after JSON escaping exact valid CSV bytes, not only before serialization',async()=>{const csv='time_s,latitude,longitude,altitude_m,ground_speed_m_s,battery_pct\n0,28,77,'+'\t'.repeat(1048200)+'1,0,99\n1,28,77,2,0,98\n';const log=await source(csv);await expect(createNotebookSourceBundle(log,[{...entries[0],first_row:1,last_row:2}])).rejects.toThrow('2MiB');});
 it('never mutates source or saved notebook',async()=>{const log=await source(),before=JSON.stringify({log,entries});await readNotebookSourceBundle(await createNotebookSourceBundle(log,entries));expect(JSON.stringify({log,entries})).toBe(before);});
});
